content:
Review this change for security vulnerabilities.

Changed files (you may Read these and any other file in the repo):
  - Silmulator/docs/learning/drills/0009-adc-reference-transfer-functions.html
  - Silmulator/docs/learning/lessons/0009-adc-reference-transfer-functions.html
  - Silmulator/docs/learning/vocab/0009-adc-reference-transfer-functions.html

Unified diff (only + lines are new):

=== DIFF: Silmulator/docs/learning/drills/0009-adc-reference-transfer-functions.html ===
@@ -0,0 +1,688 @@
+<!DOCTYPE html>
+<html lang="en">
+<head>
+<meta charset="UTF-8">
+<meta name="viewport" content="width=device-width,initial-scale=1">
+<title>Drill 0009 — ADC Reference Transfer Functions</title>
+<style>
+@media(prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}
+:root{
+  --bg:#0c1320;--surf:#18223a;--surf2:#22304e;--surf3:#2c3e62;
+  --accent:#60a5fa;--gold:#fcd34d;--green:#34d399;--red:#f87171;--orange:#fb923c;
+  --text:#dde5f5;--dim:#5a6a8a;--border:#243052;--code:#080e1c;
+  --mono:'Cascadia Code','Fira Mono','Consolas',monospace;
+}
+*{box-sizing:border-box;margin:0;padding:0}
+body{font-family:'Segoe UI',system-ui,sans-serif;background:var(--bg);color:var(--text);
+     font-size:15px;line-height:1.68;min-height:100vh}
+.screen{display:none;max-width:800px;margin:0 auto;padding:2rem 1.5rem 4rem}
+.screen.active{display:block}
+
+/* ── start ──────────────────────────────────────────────────── */
+.hd{text-align:center;margin-bottom:2.2rem}
+.lbl{font-family:var(--mono);font-size:.72rem;color:var(--dim);letter-spacing:.15em;
+     text-transform:uppercase;margin-bottom:.4rem}
+.ttl{font-size:2rem;color:#fff;margin-bottom:.4rem}
+.sub{color:var(--accent);font-size:.95rem}
+
+.chips{display:flex;flex-wrap:wrap;gap:.55rem;justify-content:center;margin:1.4rem 0}
+.chip{font-family:var(--mono);font-size:.8rem;padding:.35rem .85rem;
+      border:1px solid var(--border);border-radius:20px;cursor:pointer;
+      background:var(--surf);color:var(--dim);user-select:none;transition:all .15s}
+.chip.on{border-color:var(--accent);color:var(--accent);background:rgba(96,165,250,.1)}
+.chip.all{border-color:var(--gold);color:var(--gold);background:rgba(252,211,77,.07)}
+.chip.all.on{border-color:var(--gold);color:var(--gold)}
+
+.smeta{text-align:center;color:var(--dim);font-size:.85rem;margin-bottom:.9rem}
+.shuf{display:flex;align-items:center;justify-content:center;gap:.65rem;
+      margin-bottom:1.4rem;font-size:.86rem;color:var(--dim)}
+.tog{position:relative;display:inline-block;width:36px;height:20px}
+.tog input{opacity:0;width:0;height:0}
+.sl{position:absolute;inset:0;background:var(--surf2);border-radius:20px;cursor:pointer;transition:background .2s}
+.sl:before{content:'';position:absolute;width:14px;height:14px;left:3px;top:3px;
+           background:#fff;border-radius:50%;transition:transform .2s}
+input:checked+.sl{background:var(--accent)}
+input:checked+.sl:before{transform:translateX(16px)}
+
+/* ── question ───────────────────────────────────────────────── */
+.qhdr{display:flex;align-items:center;gap:.8rem;margin-bottom:1.5rem;flex-wrap:wrap}
+.qnum{font-family:var(--mono);font-size:.78rem;color:var(--dim)}
+.pbar{flex:1;height:5px;background:var(--surf2);border-radius:3px;min-width:80px}
+.pfill{height:100%;background:var(--accent);border-radius:3px;transition:width .3s}
+.ctag{font-family:var(--mono);font-size:.7rem;padding:.18rem .55rem;
+      border:1px solid var(--border);border-radius:12px;color:var(--dim)}
+.ttag{font-family:var(--mono);font-size:.7rem;padding:.18rem .55rem;border-radius:12px}
+.ttag.mc{background:rgba(96,165,250,.12);color:var(--accent)}
+.ttag.wr{background:rgba(251,146,60,.12);color:var(--orange)}
+
+.qtxt{font-size:1.05rem;font-weight:600;color:#fff;margin-bottom:1.1rem;line-height:1.5}
+pre.snip{background:var(--code);border:1px solid var(--border);border-radius:6px;
+         padding:.9rem 1.1rem;overflow-x:auto;font-family:var(--mono);font-size:.82rem;
+         line-height:1.6;margin-bottom:1.1rem;display:none}
+.kw{color:#c792ea}.str{color:#c3e88d}.cm{color:#405060;font-style:italic}
+.fn{color:#82aaff}.num{color:#f78c6c}.cls{color:#ffcb6b}.at{color:#a5d6ff}
+
+/* mc */
+.opts{list-style:none;margin:0;padding:0}
+.opts li{background:var(--surf);border:1px solid var(--border);border-radius:6px;
+         padding:.55rem 1rem;margin-bottom:.45rem;cursor:pointer;user-select:none;
+         transition:border-color .15s,background .15s}
+.opts li:hover:not(.lk){border-color:var(--accent);background:rgba(96,165,250,.07)}
+.opts li:focus{outline:2px solid var(--accent);outline-offset:2px}
+.opts li.ok{border-color:var(--green);background:rgba(52,211,153,.09);color:var(--green)}
+.opts li.no{border-color:var(--red);background:rgba(248,113,113,.09);color:var(--red)}
+.opts li.lk{cursor:default}
+.mfb{margin-top:.65rem;font-size:.87rem;padding:.45rem .8rem;border-radius:4px;display:none}
+.mfb.ok{background:rgba(52,211,153,.1);color:var(--green);border:1px solid rgba(52,211,153,.28)}
+.mfb.no{background:rgba(248,113,113,.09);color:var(--red);border:1px solid rgba(248,113,113,.28)}
+
+/* written */
+textarea{width:100%;min-height:108px;background:var(--surf);border:1px solid var(--border);
+         border-radius:6px;padding:.7rem .9rem;color:var(--text);font-family:inherit;
+         font-size:.92rem;resize:vertical;line-height:1.55}
+textarea:focus{outline:2px solid var(--accent)}
+.wacts{display:flex;gap:.55rem;margin-top:.65rem;flex-wrap:wrap}
+.kwres{margin-top:.8rem;display:none}
+.tally{font-weight:700;margin-bottom:.4rem;font-size:.9rem}
+.kwchips{display:flex;flex-wrap:wrap;gap:.35rem;margin-bottom:.55rem}
+.kc{font-family:var(--mono);font-size:.75rem;padding:.18rem .5rem;border-radius:12px}
+.kc.h{background:rgba(52,211,153,.12);color:var(--green);border:1px solid rgba(52,211,153,.28)}
+.kc.m{background:rgba(248,113,113,.1);color:var(--red);border:1px solid rgba(248,113,113,.28)}
+.knote{color:var(--dim);font-size:.78rem}
+.modans{display:none;margin-top:.8rem;background:var(--surf);border:1px solid var(--border);
+        border-radius:6px;padding:.8rem 1rem;font-size:.9rem;line-height:1.65;white-space:pre-wrap}
+.modlbl{font-family:var(--mono);font-size:.7rem;color:var(--dim);text-transform:uppercase;
+        letter-spacing:.08em;margin-bottom:.35rem}
+.sr{display:none;align-items:center;gap:.5rem;flex-wrap:wrap;
+    font-size:.85rem;color:var(--dim);margin-top:.65rem}
+
+/* nav + buttons */
+.nav{display:flex;gap:.55rem;margin-top:1.5rem;flex-wrap:wrap;align-items:center}
+.spc{flex:1}
+.btn{font-family:var(--mono);font-size:.83rem;padding:.45rem 1rem;border:1px solid transparent;
+     border-radius:5px;cursor:pointer;transition:opacity .15s;user-select:none}
+.btn:focus{outline:2px solid var(--accent);outline-offset:2px}
+.pri{background:var(--accent);color:#000}.pri:hover{opacity:.82}
+.sec{background:var(--surf2);color:var(--text);border-color:var(--border)}
+.sec:hover{border-color:var(--accent)}
+.grn{background:var(--green);color:#000}
+.gld{background:var(--gold);color:#000}
+.sm{padding:.32rem .7rem;font-size:.77rem}
+.red{background:var(--red);color:#fff}
+
+/* results */
+.rhdr{text-align:center;margin-bottom:1.8rem}
+.sbig{font-size:3.4rem;font-family:var(--mono);color:var(--accent)}
+.slbl{color:var(--dim);font-size:.88rem;margin-top:.25rem}
+.rcols{display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin:1.4rem 0}
+@media(max-width:520px){.rcols{grid-template-columns:1fr}}
+.rcard{background:var(--surf);border:1px solid var(--border);border-radius:7px;padding:.9rem 1.1rem}
+.rcard h3{font-family:var(--mono);font-size:.78rem;color:var(--dim);
+          text-transform:uppercase;letter-spacing:.08em;margin-bottom:.6rem}
+.miss{background:var(--surf2);border-radius:4px;padding:.38rem .65rem;
+      margin-bottom:.38rem;font-size:.86rem}
+.mcorr{color:var(--green);font-family:var(--mono);font-size:.8rem;display:block;margin-top:.2rem}
+</style>
+</head>
+<body>
+
+<!-- ═══════════ START ═══════════ -->
+<div id="S" class="screen active">
+<div class="hd">
+  <div class="lbl">Drill 0009 · Active Recall</div>
+  <div class="ttl">ADC Reference Transfer Functions</div>
+  <div class="sub">24 questions — Eq. 13 math, the reference set, commit 58b7e2d code, clipping &amp; LSB, SIL bug-hunting</div>
+</div>
+<p style="text-align:center;color:var(--dim);font-size:.87rem;margin-bottom:1rem">Pick channels to drill, or keep All.</p>
+<div class="chips" id="chips">
+  <div class="chip all on" data-ch="all">⚡ All</div>
+  <div class="chip on" data-ch="transfer">Transfer function math</div>
+  <div class="chip on" data-ch="refs">Reference set &amp; validation</div>
+  <div class="chip on" data-ch="code">Real code (58b7e2d)</div>
+  <div class="chip on" data-ch="clip">Full scale, clipping, LSB</div>
+  <div class="chip on" data-ch="sil">SIL bug-hunting</div>
+</div>
+<p class="smeta" id="smeta">24 questions selected</p>
+<div class="shuf">
+  Shuffle
+  <label class="tog"><input type="checkbox" id="sh" checked><span class="sl"></span></label>
+</div>
+<div style="text-align:center">
+  <button class="btn pri" onclick="go()" style="font-size:1rem;padding:.65rem 2rem">Begin →</button>
+</div>
+</div>
+
+<!-- ═══════════ QUESTION ═══════════ -->
+<div id="Q" class="screen">
+<div class="qhdr">
+  <span class="qnum" id="qn">Q 1 / 24</span>
+  <div class="pbar"><div class="pfill" id="pf" style="width:0%"></div></div>
+  <span class="ctag" id="ct"></span>
+  <span class="ttag mc" id="tt">MC</span>
+</div>
+<div class="qtxt" id="qt"></div>
+<pre class="snip" id="qs"></pre>
+
+<div id="MA" style="display:none">
+  <ul class="opts" id="mo"></ul>
+  <div class="mfb" id="mf"></div>
+</div>
+
+<div id="WA" style="display:none">
+  <textarea id="wa" placeholder="Type your answer here…"></textarea>
+  <div class="wacts">
+    <button class="btn sec sm" onclick="chkW()">Check keywords</button>
+    <button class="btn sec sm" onclick="showM()">Show model answer</button>
+  </div>
+  <div class="kwres" id="kr">
+    <div class="tally" id="kt"></div>
+    <div class="kwchips" id="kc"></div>
+    <div class="knote">⚠ Keyword check is fuzzy — judge honestly against the model answer.</div>
+  </div>
+  <div class="modans" id="md"><div class="modlbl">Model answer</div><div id="mt"></div></div>
+  <div class="sr" id="sr">
+    Rate yourself:
+    <button class="btn grn sm" onclick="rate('k')">✓ Knew it</button>
+    <button class="btn red sm"  onclick="rate('r')">↺ Needs review</button>
+  </div>
+</div>
+
+<div class="nav">
+  <button class="btn sec sm" id="bp" onclick="prev()">← Prev</button>
+  <div class="spc"></div>
+  <button class="btn pri sm" id="bn" onclick="next()">Next →</button>
+  <button class="btn gld sm" id="bf" style="display:none" onclick="results()">Results</button>
+</div>
+</div>
+
+<!-- ═══════════ RESULTS ═══════════ -->
+<div id="R" class="screen">
+<div class="rhdr">
+  <div class="sbig" id="rb">—</div>
+  <div class="slbl" id="rl"></div>
+</div>
+<div class="rcols">
+  <div class="rcard"><h3>MC misses</h3><div id="rm"><em style="color:var(--dim);font-size:.86rem">None!</em></div></div>
+  <div class="rcard"><h3>Written — needs review</h3><div id="rw"><em style="color:var(--dim);font-size:.86rem">None flagged.</em></div></div>
+</div>
+<div style="display:flex;gap:.6rem;justify-content:center;flex-wrap:wrap;margin-top:.8rem">
+  <button class="btn sec" onclick="rev()">Review missed only</button>
+  <button class="btn pri" onclick="location.reload()">Restart</button>
+</div>
+</div>
+
+<script>
+// ══════════════════════════════════════════════════════════════
+// QUESTION BANK  (22 questions — grounded in commit 58b7e2d)
+// ══════════════════════════════════════════════════════════════
+const BANK = [
+
+// ─── CHANNEL: transfer ────────────────────────────────────────
+{id:'t1',ch:'transfer',type:'w',
+ q:'Write out the ADC12_B transfer function from SLAU367P §34.2.1 (Eq. 13) and explain what each of the four quantities means. What does the equation simplify to in Silmulator\'s model, and why?',
+ c:[{l:'NADC = FS × (Vin − VR−)/(VR+ − VR−)',t:['4095','fs ×','(vin','vr−','vr-','vr+']},
+    {l:'VR+ = positive reference (full-scale voltage)',t:['vr+','positive reference','full scale','full-scale']},
+    {l:'VR− = negative reference (code-0 voltage)',t:['vr−','vr-','negative reference','code 0','zero']},
+    {l:'VR− fixed at AVSS (0 V) → N = FS × Vin/VR+',t:['avss','0 v','fixed','simplif','vin / vr','vin/vr']}],
+ m:`NADC = FS × (Vin − VR−) / (VR+ − VR−), where FS = 2^resolution − 1 (4095 in 12-bit mode).
+- Vin: the analog input voltage on the selected channel.
+- VR+: the positive reference — the voltage that produces the full-scale code. Selected by ADC12VRSEL.
+- VR−: the negative reference — the voltage that produces code 0.
+- FS: the full-scale code (4095 / 1023 / 255 for 12/10/8-bit ADC12RES modes).
+In Silmulator, VR− is fixed at AVSS (0 V) — the _adc_reference_voltage() docstring says the model only exposes which source drives VR+, not the VR− half of ADC12VRSEL's combinations. So the equation simplifies to N = FS × Vin / VR+, implemented as int(voltage / full_scale_v * max_code), clamped to [0, max_code].`
+},
+
+{id:'t2',ch:'transfer',type:'mc',
+ q:'ADC:REFERENCE AVCC is selected (CPU:VCC at its 3.3-V default) and 1.2 V is injected on channel 0. What does ADC:CHANNEL0:RAW? return in 12-bit mode?',
+ snip:`<span class="cm"># msp430_faults.py — nominal profile</span>
+code = int(voltage / full_scale_v * max_code)
+<span class="kw">return</span> max(<span class="num">0</span>, min(max_code, code))`,
+ opts:[
+  {t:'1489',c:true, w:'Correct. int(1.2 / 3.3 × 4095) = int(1489.09) = 1489 — about 36% of the reference span.'},
+  {t:'4095',c:false,w:'4095 would require Vin ≥ VR+. That happens with the same 1.2-V input only when the 1.2-V VREF is the selected reference.'},
+  {t:'1490',c:false,w:'int() truncates: 1489.09 → 1489. There is no rounding to nearest in adc_code().'},
+  {t:'1229',c:false,w:'1229 ≈ int(1.2/4.0×4095) — wrong reference voltage. AVCC defaults to 3.3 V (clock.vcc).'},
+ ]
+},
+
+{id:'t3',ch:'transfer',type:'mc',
+ q:'Same 1.2-V injection on channel 0, but now the test first sends ADC:REFERENCE VREF. What does ADC:CHANNEL0:RAW? return?',
+ opts:[
+  {t:'4095 — the input equals the 1.2-V reference, so it reads full scale',c:true, w:'Correct. Bare VREF maps to REFVSEL\'s reset default (00b = 1.2 V) via ADC_INTERNAL_REF_V. N = 4095 × 1.2/1.2 = 4095. This is exactly test_raw_respects_selected_reference and the adc_ignores_reference audit probe.'},
+  {t:'1489 — the reference selection is stored but conversions always use 3.3 V',c:false,w:'That was the pre-58b7e2d bug. The fix makes _adc_ch_raw call _adc_reference_voltage(), so VREF (1.2 V) is actually used.'},
+  {t:'2047 — VREF means half of AVCC',c:false,w:'VREF is REF_A\'s internal 1.2-V output (REFVSEL reset value), not a fraction of the supply.'},
+  {t:'SCPI error -224 — bare VREF is ambiguous and must be VREF1.2/2.0/2.5',c:false,w:'Bare VREF is valid: it maps to the REFVSEL reset default of 1.2 V in ADC_INTERNAL_REF_V.'},
+ ]
+},
+
+{id:'t4',ch:'transfer',type:'w',
+ q:'A 0.6-V signal is injected on channel 5. Compute the 12-bit RAW code under each of these three references: VREF1.2, VREF2.5, and AVCC (3.3 V). Show your arithmetic, including the truncation step.',
+ c:[{l:'VREF1.2 → 2047 (0.6/1.2×4095 = 2047.5, truncated)',t:['2047']},
+    {l:'VREF2.5 → 982 (0.6/2.5×4095 = 982.8)',t:['982']},
+    {l:'AVCC 3.3 → 744 (0.6/3.3×4095 = 744.5)',t:['744']},
+    {l:'int() truncates toward zero',t:['truncat','int(','toward zero','floor']}],
+ m:`All use N = int(0.6 / VR+ × 4095):
+- VREF1.2: 0.6/1.2 = 0.5 → 0.5 × 4095 = 2047.5 → int() truncates → 2047
+- VREF2.5: 0.6/2.5 = 0.24 → 0.24 × 4095 = 982.8 → 982
+- AVCC 3.3: 0.6/3.3 ≈ 0.1818 → × 4095 = 744.54 → 744
+Same physical voltage, three different codes — the code is a fraction of the selected reference, not a voltage. Note int() truncates toward zero (2047.5 → 2047, never 2048).`
+},
+
+{id:'t5',ch:'transfer',type:'mc',
+ q:'Firmware reads code 2047 from a 12-bit conversion. Which statement is the ONLY safe conclusion?',
+ opts:[
+  {t:'The input is at roughly half of whatever reference span was selected for the conversion',c:true, w:'Correct. 2047/4095 ≈ 0.5 — a ratio. It could be ~0.6 V (VREF), ~1.25 V (VREF2.5), or ~1.65 V (AVCC at 3.3). Without knowing VR+, the code carries no voltage information.'},
+  {t:'The input voltage is approximately 1.65 V',c:false,w:'Only true if VR+ happened to be 3.3 V. Under VREF (1.2 V) the same code means ~0.6 V. The code alone does not determine the voltage.'},
+  {t:'The ADC is misconfigured, because 2047 is not a power of two',c:false,w:'Codes can be any integer in [0, 4095]. There is nothing special or wrong about 2047.'},
+  {t:'The input exceeds the reference and the result has clipped',c:false,w:'Clipping pegs the code at 4095 (full scale), not 2047.'},
+ ]
+},
+
+// ─── CHANNEL: refs ────────────────────────────────────────────
+{id:'r1',ch:'refs',type:'w',
+ q:'List every token ADC:REFERENCE accepts after commit 58b7e2d, the VR+ voltage each one selects, and the physical source it models.',
+ c:[{l:'AVCC → clock.vcc live (supply rail)',t:['avcc','clock.vcc','cpu:vcc','supply','3.3']},
+    {l:'VREF / VREF1.2 → 1.2 V (REFVSEL reset default)',t:['vref','1.2','reset default','00b']},
+    {l:'VREF2.0 → 2.0 V; VREF2.5 → 2.5 V (REF_A outputs)',t:['2.0','2.5','ref_a','internal']},
+    {l:'VEREF → _veref_v, external VeREF+ pin, settable via 2nd param',t:['veref','external','pin','_veref_v','second param','2.1']}],
+ m:`VALID_ADC_REFERENCES = frozenset({"AVCC", "VEREF"} | set(ADC_INTERNAL_REF_V)) — six tokens:
+- AVCC → whatever CPU:VCC currently is (read live from clock.vcc; default 3.3 V). Models the analog supply rail.
+- VREF → 1.2 V. Bare VREF maps to REFVSEL's reset value (00b = 1.2 V) in REF_A.
+- VREF1.2 → 1.2 V, VREF2.0 → 2.0 V, VREF2.5 → 2.5 V. REF_A's three internal bandgap-derived outputs (SLAU367P §33.3.1).
+- VEREF → self._veref_v (default 1.2 V; reset by *RST). Models the external VeREF+ pin; the board-supplied voltage is settable with a second parameter, e.g. ADC:REFERENCE VEREF,2.1.
+Anything else has no ADC12VRSEL encoding → ScpiError -224.`
+},
+
+{id:'r2',ch:'refs',type:'mc',
+ q:'A test script sends ADC:REFERENCE BANANA. Per the fixed code and probe_adc_reference_unvalidated, what is the device state afterwards?',
+ snip:`<span class="cm"># scripts/audit_msp430.py — after 58b7e2d</span>
+<span class="kw">def</span> <span class="fn">probe_adc_reference_unvalidated</span>(dev):
+    <span class="str">"""Reference is validated against the fixed ADC12VRSEL/REF_A set."""</span>
+    dev.process(<span class="str">"ADC:REFERENCE BANANA"</span>)
+    <span class="kw">return</span> _errors(dev) == <span class="num">1</span> <span class="kw">and</span> dev.adc[<span class="num">0</span>].reference == <span class="str">"AVCC"</span>`,
+ opts:[
+  {t:'One SCPI error (-224) is queued and the reference is still the AVCC default — the bad value is never stored',c:true, w:'Correct. _adc_ref raises ScpiError(-224, "Illegal ADC reference: BANANA") BEFORE the loop that assigns ch.reference, so channel state is untouched. The probe asserts exactly this: errors == 1 and reference == "AVCC".'},
+  {t:'The reference is set to BANANA and conversions fall back to 3.3 V',c:false,w:'That was the OLD behaviour (any string accepted, never used). The validation now rejects it before storage.'},
+  {t:'Error -224 is queued but the reference is also cleared to VREF as a safe default',c:false,w:'Rejection leaves prior state unchanged — it does not reset to some other default. The probe checks reference == "AVCC" because AVCC was the state before the bad command.'},
+  {t:'The command is silently ignored with no error',c:false,w:'SCPI devices report bad parameters via the error queue. The probe requires _errors(dev) == 1.'},
+ ]
+},
+
+{id:'r3',ch:'refs',type:'mc',
+ q:'Why does the simulator reject ADC:REFERENCE 1.8 rather than supporting arbitrary reference voltages?',
+ opts:[
+  {t:'The real ADC12VRSEL register field has a finite set of encodings — there is no silicon path that produces an arbitrary 1.8-V reference',c:true, w:'Correct. VR+ must come from a physical source: AVCC, one of REF_A\'s three bandgap outputs, or the external VeREF+ pin. A free-form voltage would let SIL tests bless configurations no hardware can express — the simulator must mirror the register\'s value set.'},
+  {t:'Floating-point parameters are not supported by the SCPI parser',c:false,w:'The parser handles floats fine — ADC:REFERENCE VEREF,2.1 takes one. The rejection is about hardware fidelity, not parsing.'},
+  {t:'1.8 V would exceed the maximum safe reference for the FR5994',c:false,w:'2.5-V and 3.3-V references are valid, so 1.8 V is not out of range. It simply corresponds to no ADC12VRSEL encoding.'},
+  {t:'It is a temporary limitation until REF_A trimming is modelled',c:false,w:'It is deliberate and permanent: the accepted set mirrors the hardware\'s selectable sources. (What IS still missing from REF_A is REFCTL0 semantics — REFON/REFOUT bits etc.)'},
